local old
old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
    local Args = {...}
    local method = getnamecallmethod()

    if method == "FireServer" and self.Name == "CollectItem" and not checkcaller() then
        Args[1] = 9000000000000000

        return old(self, unpack(Args))
    end
    return old(self, ...)
end))
